// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;

    function setUp() public { c = new MultiplicatorX3(); }

    function testFuzz_property(uint256 amount, bytes memory data) public {
        vm.assume(amount >= 1);
        amount = bound(amount, 1, 1e36);

        Receiver target = new Receiver();

        address owner = c.Owner();
        vm.deal(owner, amount + 1 ether);

        uint256 balanceBefore = address(target).balance;

        vm.prank(owner);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.Command.selector, address(target), data));
        require(success, "Command call failed");

        uint256 balanceAfter = address(target).balance;
        assertTrue(balanceAfter - balanceBefore == amount);
    }
}

contract Receiver {
    fallback() external payable {}
}
